Layer.GoOffMessageCommand:
%function(self)
			self:bounceend(0.3);
				if Mode2Selected then 
					self:diffuse(1,1,1,1);
					self:glowblink();
					self:effectperiod(0.2)
					self:zoom(1);
					self:zoomx(0.95)
					self:sleep(0.5)
					self:accelerate(0.3)
					self:x(1500)
				else
					self:z(0);
					self:zoom(0);
				end
			end
